INSERT INTO questions(id,data) VALUES
('9g3-w10-p246-q10-description',$question_json${"id":"9g3-w10-p246-q10-description","classroom":"9G3","examWeek":10,"exam":"9G3 · 10th week practice","topic":"Apply dilations to linear functions","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"The parent function is $f(x)=x$, shown on the graph. For $g(x)=f(5x)$, which statement describes the horizontal dilation?","promptAr":"الدالة الأم $f(x)=x$ موضحة بالرسم. أي عبارة تصف التمدد الأفقي في $g(x)=f(5x)$؟","answer":"Replacing $x$ with $kx$ scales horizontal distances by $1/k$. Here $k=5>0$, so the factor is $\\frac15$ and the graph compresses horizontally. Also $g(x)=5x$, so it passes through the origin with slope $5$.","answerAr":"التعويض عن $x$ بـ $kx$ يضرب المسافات الأفقية في $1/k$. هنا $k=5>0$، لذا المعامل $\\frac15$ ويحدث انضغاط أفقي. كما أن $g(x)=5x$، فيمر الرسم بنقطة الأصل وميله $5$.","options":["Horizontal compression by a factor of $\\frac15$.","Horizontal stretch by a factor of $\\frac15$.","Translation 5 units to the right.","Reflection across the y-axis and scaling by $\\frac15$."],"optionsAr":["انضغاط أفقي بمعامل $\\frac15$.","تمدد أفقي بمعامل $\\frac15$.","إزاحة إلى اليمين بمقدار $5$ وحدة.","انعكاس حول محور الصادات وتمدد بمعامل $\\frac15$."],"sourcePage":246,"sourceQuestion":10,"sourcePart":"description","linearGraph":{"coefficients":[1,0],"bounds":[-5,5,-5,5]},"linearFunctionDilation":{"k":5,"kind":"description"},"correctIndex":0}$question_json$::jsonb),
('9g3-w10-p246-q10-graph',$question_json${"id":"9g3-w10-p246-q10-graph","classroom":"9G3","examWeek":10,"exam":"9G3 · 10th week practice","topic":"Apply dilations to linear functions","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"The parent function is $f(x)=x$. Which graph represents $g(x)=f(5x)$? All graphs use the same unit scale.","promptAr":"الدالة الأم $f(x)=x$. أي رسم يمثل $g(x)=f(5x)$؟ الرسوم تستخدم المقياس نفسه.","answer":"Replacing $x$ with $kx$ scales horizontal distances by $1/k$. Here $k=5>0$, so the factor is $\\frac15$ and the graph compresses horizontally. Also $g(x)=5x$, so it passes through the origin with slope $5$.","answerAr":"التعويض عن $x$ بـ $kx$ يضرب المسافات الأفقية في $1/k$. هنا $k=5>0$، لذا المعامل $\\frac15$ ويحدث انضغاط أفقي. كما أن $g(x)=5x$، فيمر الرسم بنقطة الأصل وميله $5$.","options":["Graph D","Graph A","Graph B","Graph C"],"optionsAr":["الرسم D","الرسم A","الرسم B","الرسم C"],"sourcePage":246,"sourceQuestion":10,"sourcePart":"graph","linearFunctionDilation":{"k":5,"kind":"graph"},"linearChoices":{"bounds":[-5,5,-5,5],"target":{"kind":"line","m":5,"b":0},"choices":[{"kind":"line","m":1,"b":5},{"kind":"line","m":5,"b":0},{"kind":"line","m":0.2,"b":0},{"kind":"line","m":-5,"b":0}]},"correctIndex":1}$question_json$::jsonb),
('9g3-w10-p246-q11-description',$question_json${"id":"9g3-w10-p246-q11-description","classroom":"9G3","examWeek":10,"exam":"9G3 · 10th week practice","topic":"Apply dilations to linear functions","type":"MCQ","marks":1,"difficulty":"Standard","diagram":"none","image":"","prompt":"The parent function is $f(x)=x$, shown on the graph. For $g(x)=f(\\frac13x)$, which statement describes the horizontal dilation?","promptAr":"الدالة الأم $f(x)=x$ موضحة بالرسم. أي عبارة تصف التمدد الأفقي في $g(x)=f(\\frac13x)$؟","answer":"Replacing $x$ with $kx$ scales horizontal distances by $1/k$. Here $k=\\frac13>0$, so the factor is $3$ and the graph stretches horizontally. Also $g(x)=\\frac13x$, so it passes through the origin with slope $\\frac13$.","answerAr":"التعويض عن $x$ بـ $kx$ يضرب المسافات الأفقية في $1/k$. هنا $k=\\frac13>0$، لذا المعامل $3$ ويحدث تمدد أفقي. كما أن $g(x)=\\frac13x$، فيمر الرسم بنقطة الأصل وميله $\\frac13$.","options":["Translation \\frac13 units to the right.","Reflection across the y-axis and scaling by $3$.","Horizontal stretch by a factor of $3$.","Horizontal compression by a factor of $3$."],"optionsAr":["إزاحة إلى اليمين بمقدار $\\frac13$ وحدة.","انعكاس حول محور الصادات وتمدد بمعامل $3$.","تمدد أفقي بمعامل $3$.","انضغاط أفقي بمعامل $3$."],"sourcePage":246,"sourceQuestion":11,"sourcePart":"description","linearGraph":{"coefficients":[1,0],"bounds":[-5,5,-5,5]},"linearFunctionDilation":{"k":0.3333333333333333,"kind":"description"},"correctIndex":2}$question_json$::jsonb),
